/** Saved demos (a recorded clip plus its Presage telemetry), shared by main and renderer. */

/** Video containers the app saves and imports (Chromium plays all of them). */
export const VIDEO_TYPES: Readonly<Record<string, string>> = Object.freeze({
  webm: 'video/webm',
  mp4: 'video/mp4',
  m4v: 'video/mp4',
  mov: 'video/quicktime',
  mkv: 'video/x-matroska',
  ogv: 'video/ogg',
});
/** Largest clip the library accepts (bytes). */
export const MAX_VIDEO_BYTES = 1024 * 1024 * 1024;
export const MAX_DEMO_NAME = 60;
export const MAX_DEMO_NOTES = 500;
/** Demo ids are generated by the library: lowercase slug + time stamp. */
export const DEMO_ID = /^[a-z0-9][a-z0-9-]{0,79}$/;

export interface DemoSummary {
  id: string;
  name: string;
  notes: string;
  createdAt: string;
  durationMs: number;
  frames: number;
  includesBody: boolean;
  /** File name of the clip inside the demo folder (video.<ext>). */
  videoFile: string;
  videoBytes: number;
}

export interface DemoLibraryListing {
  /** Absolute folder the demos are kept in. */
  dir: string;
  /** True when it is the default folder inside the app's data directory. */
  isDefault: boolean;
  demos: DemoSummary[];
  /** Folders that could not be read (shown, never deleted). */
  broken: string[];
}

export interface DemoSaveRequest {
  name: string;
  notes?: string;
  /** Telemetry as produced by TelemetryRecorder (validated again in main). */
  telemetry: unknown;
  video: Uint8Array;
  /** Container extension, e.g. "webm" (a key of VIDEO_TYPES). */
  ext: string;
}

export interface DemoLoaded {
  summary: DemoSummary;
  telemetry: unknown;
  video: Uint8Array;
  mime: string;
}

export function videoExt(fileName: string): string | null {
  const m = /\.([a-z0-9]+)$/i.exec(fileName);
  const ext = m?.[1]?.toLowerCase();
  return ext && ext in VIDEO_TYPES ? ext : null;
}

export function cleanName(v: unknown, fallback = 'Untitled demo'): string {
  const s =
    typeof v === 'string'
      ? [...v]
          .map((c) => (c.charCodeAt(0) < 32 || c.charCodeAt(0) === 127 ? ' ' : c))
          .join('')
          .trim()
      : '';
  return (s || fallback).slice(0, MAX_DEMO_NAME);
}

export function formatDuration(ms: number): string {
  const s = Math.max(0, Math.round(ms / 1000));
  return `${Math.floor(s / 60)}:${String(s % 60).padStart(2, '0')}`;
}
